import html2canvas from 'html2canvas'

export const mytitlebothfun = {
  bind: (el, binding) => {
    el.innerHTML = `
    <div style="width: 500px; height:250px; background:lightblue;position: relative;cursor: pointer;">
      <div style="width: 150px; height:150px;display: inline-block;margin:20px 50px 50px 50px;position: absolute;left: 30px;overflow:hidden;border:1px dashed;">
        <input type="file" name="file" id="bothFile" style="z-index: 333;opacity:0;width: 100%; height: 100%;cursor: pointer;position: absolute;top:0px;left:0px;" >
      </div>
      <div style="width: 120px; height:120px;display: inline-block; margin:65px;position: absolute;right: 1px;">
        <div class="div1" style="position: absolute;top:0px;left:0px;width: 100%; height: 100%;z-index:111;background: rgba(0, 0, 0, 0.4)"></div>
      </div>
      <div style="position: absolute;top: 170px;left: 95px;height: 10px;">
        <span id="myadd" style="border: 1px solid blue;color: blue;border-radius: 50%;height: 15px;text-align: center; width: 15px;display: inline-block; line-height: 12px;margin: 10px;">+</span>
        <span id="mysub" style="border: 1px solid blue;color: blue;border-radius: 50%;height: 15px;text-align: center; width: 15px;display: inline-block; line-height: 12px;margin: 10px;">-</span>
        <span id="mydel" style="border: 1px solid blue;color: blue;border-radius: 50%;height: 15px;text-align: center; width: 15px;display: inline-block; line-height: 12px;margin: 10px;transform: rotate(45deg);">+</span>
      </div>
      <button id="bothBut1" style="position:absolute;left: 30%;transform: translate(-50%, 0);bottom: 10px;">预览</button>
      <button id="bothBut2" style="position:absolute;left: 60%;transform: translate(-50%, 0);bottom: 10px;">上传</button>
    </div>`
  },
  inserted: (el, binding) => {
    var file = document.getElementById('bothFile')
    mytitlefun.bind(file, binding)
    var bothBut1 = document.getElementById('bothBut1')
    var bothBut2 = document.getElementById('bothBut2')
    var myadd = document.getElementById('myadd')
    var mysub = document.getElementById('mysub')
    var mydel = document.getElementById('mydel')
    var bothH = 0
    var bothW = 0
    var bothT = 0
    var bothL = 0
    myadd.onclick = () => {
      if (el.firstElementChild.firstElementChild.lastElementChild.nodeName === 'IMG') {
        bothH = el.firstElementChild.firstElementChild.lastElementChild.offsetHeight
        bothW = el.firstElementChild.firstElementChild.lastElementChild.offsetWidth
        bothH += 20
        bothW += 20
        bothT -= 10
        bothL -= 10
        el.firstElementChild.firstElementChild.lastElementChild.style.height = bothH + 'px'
        el.firstElementChild.firstElementChild.lastElementChild.style.width = bothW + 'px'
        el.firstElementChild.firstElementChild.lastElementChild.style.top = bothT + 'px'
        el.firstElementChild.firstElementChild.lastElementChild.style.left = bothL + 'px'
      }
    }
    mysub.onclick = () => {
      if (el.firstElementChild.firstElementChild.lastElementChild.nodeName === 'IMG') {
        bothH = el.firstElementChild.firstElementChild.lastElementChild.offsetHeight
        bothW = el.firstElementChild.firstElementChild.lastElementChild.offsetWidth
        bothH -= 20
        bothW -= 20
        bothT += 10
        bothL += 10
        el.firstElementChild.firstElementChild.lastElementChild.style.height = bothH + 'px'
        el.firstElementChild.firstElementChild.lastElementChild.style.width = bothW + 'px'
        el.firstElementChild.firstElementChild.lastElementChild.style.top = bothT + 'px'
        el.firstElementChild.firstElementChild.lastElementChild.style.left = bothL + 'px'
      }
    }
    mydel.onclick = () => {
      if (el.firstElementChild.firstElementChild.lastElementChild.nodeName === 'IMG') {
        el.firstElementChild.firstElementChild.removeChild(el.firstElementChild.firstElementChild.lastElementChild)
      }
    }
    var bothdataURL = ''
    bothBut1.addEventListener('click', function () {
      html2canvas(el.firstElementChild.firstElementChild, {
        allowTaint: true,
        useCORS: true,
        backgroundColor: null
      }).then((canvas) => {
        bothdataURL = canvas.toDataURL('image/png', 0)
        const myimgarr = el.firstElementChild.firstElementChild.nextElementSibling.childNodes
        if (myimgarr.length !== 0) {
          Array.from(myimgarr).forEach(item => {
            el.firstElementChild.firstElementChild.nextElementSibling.removeChild(item)
          })
        }
        bothBut2.addEventListener('click', function dataURLtoFile () { // 将base64转换为文件
          var arr = bothdataURL.split(',')
          var mime = arr[0].match(/:(.*?);/)[1]
          var bstr = atob(arr[1])
          var n = bstr.length
          var u8arr = new Uint8Array(n)
          while (n--) {
            u8arr[n] = bstr.charCodeAt(n)
          }
          if (!binding.value.filename) { binding.value.file = new File([u8arr], 'filename', { type: mime }) } else {
            binding.value.file = new File([u8arr], binding.value.filename, { type: mime })
          }
        })
        const img1 = document.createElement('img')
        img1.style.cssText = 'position: absolute;top:0px;left:0px;width: 100%; height: 100%;'
        img1.src = bothdataURL
        img1.className = 'myimgarr'
        el.firstElementChild.firstElementChild.nextElementSibling.insertBefore(img1, el.firstElementChild.firstElementChild.nextElementSibling[0])
        const div1 = document.createElement('div')
        div1.style.cssText = 'position: absolute;top:0px;left:0px;width: 100%; height: 100%;z-index:111;background: rgba(0, 0, 0, 0.4)'
        div1.className = 'div1'
        el.firstElementChild.firstElementChild.nextElementSibling.insertBefore(div1, el.firstElementChild.firstElementChild.nextElementSibling[0])
        const img2 = document.createElement('img')
        img2.style.cssText = 'position: absolute;top:0px;left:0px;width: 100%; height: 100%;border-radius: 50%;z-index:222;'
        img2.src = bothdataURL
        img1.className = 'myimgarr'
        el.firstElementChild.firstElementChild.nextElementSibling.insertBefore(img2, el.firstElementChild.firstElementChild.nextElementSibling[0])
      })
    })
  }
}

export const mytitlefun = {
  bind: (el, binding) => {
    el.addEventListener('change', function () {
      var URLT = window.URL || window.webkitURL
      var titleURL = URLT.createObjectURL(Array.from(this.files)[0])
      var img = document.createElement('img')
      img.src = titleURL
      img.style.cssText = 'position: absolute;top:0px;left:0px;width: 100%; height: 100%;z-index: 555;'
      img.addEventListener('mouseenter', () => {
        img.style.position = 'absolute'
        img.onmousedown = function (event) {
          img.style.position = 'absolute'
          var boxleft = 0
          var boxtop = 0
          var topY = event.clientY - img.offsetTop
          var leftX = event.clientX - img.offsetLeft
          window.onmousemove = function (event) {
            boxleft = event.clientX - leftX
            boxtop = event.clientY - topY
            img.style.left = boxleft + 'px'
            img.style.top = boxtop + 'px'
          }
          window.onmouseup = function () {
            window.onmousemove = null
          }
          return false
        }
      })
      el.parentNode.insertBefore(img, el.parentNode[0])
    })
  }
}

